if($action==='page_context'){$url=trim((string)($input['url']??''));if(!filter_var($url,FILTER_VALIDATE_URL))json_response(['ok'=>false,'error'=>['code'=>'INVALID_URL']],422);$source=ensure_source($pdo,$url,$input['title']??null,$input['media_type']??null);$q=$pdo->prepare("SELECT COUNT(*) FROM annotations WHERE source_id=? AND visibility='public' AND status='published'");$q->execute([$source['id']]);$count=(int)$q->fetchColumn();$u=current_user($pdo);$followingCount=0;if($u){$q=$pdo->prepare("SELECT COUNT(*) FROM annotations a JOIN follows f ON f.followed_user_id=a.user_id AND f.follower_user_id=? WHERE a.source_id=? AND a.visibility='public' AND a.status='published'");$q->execute([$u['id'],$source['id']]);$followingCount=(int)$q->fetchColumn();}$presence=0;try{$q=$pdo->prepare('SELECT COUNT(*) FROM page_presence_sessions WHERE source_id=? AND last_seen_at>=DATE_SUB(NOW(),INTERVAL 90 SECOND) AND presence_mode<>"off"');$q->execute([$source['id']]);$presence=(int)$q->fetchColumn();}catch(PDOException $e){}json_response(['ok'=>true,'data'=>['source'=>['public_id'=>$source['public_id'],'title'=>$source['title'],'canonical_url'=>$source['canonical_url'],'status'=>$source['status']],'annotation_count'=>$count,'following_annotation_count'=>$followingCount,'presence_count'=>$presence,'authenticated'=>(bool)$u,'presence_mode'=>$u['live_presence_mode']??'off']]);}
if($action==='feed_page'||$action==='feed_following'){$u=current_user($pdo);$uid=(int)($u['id']??0);$common="SELECT a.public_id,a.text_commentary,a.audio_commentary_path,a.published_at,a.user_id,u2.public_id author_public_id,u2.username,u2.display_name,s.title source_title,s.canonical_url,s.status source_status,c.capture_type,c.selected_text,c.start_seconds,c.end_seconds,c.screenshot_target_path,(SELECT COUNT(*) FROM comments cm WHERE cm.annotation_id=a.id) comment_count,".($uid?"EXISTS(SELECT 1 FROM follows f2 WHERE f2.follower_user_id=$uid AND f2.followed_user_id=a.user_id)":"0")." is_following,".($uid?"EXISTS(SELECT 1 FROM saved_annotations sa WHERE sa.user_id=$uid AND sa.annotation_id=a.id)":"0")." is_saved FROM annotations a JOIN users u2 ON u2.id=a.user_id JOIN sources s ON s.id=a.source_id JOIN captures c ON c.id=a.capture_id ";if($action==='feed_page'){$source=(string)($input['source']??'');$sql=$common."WHERE s.public_id=? AND a.visibility='public' AND a.status='published'".($uid?" AND NOT EXISTS(SELECT 1 FROM blocks b WHERE (b.blocker_user_id=$uid AND b.blocked_user_id=a.user_id) OR (b.blocker_user_id=a.user_id AND b.blocked_user_id=$uid))":"")." ORDER BY a.published_at DESC LIMIT 50";$q=$pdo->prepare($sql);$q->execute([$source]);}else{$u=require_api_user($pdo);$sql=$common."JOIN follows f ON f.followed_user_id=a.user_id WHERE f.follower_user_id=? AND a.visibility='public' AND a.status='published' AND NOT EXISTS(SELECT 1 FROM blocks b WHERE (b.blocker_user_id=? AND b.blocked_user_id=a.user_id) OR (b.blocker_user_id=a.user_id AND b.blocked_user_id=?)) ORDER BY a.published_at DESC LIMIT 50";$q=$pdo->prepare($sql);$q->execute([$u['id'],$u['id'],$u['id']]);}json_response(['ok'=>true,'data'=>['annotations'=>$q->fetchAll()]]);}
if($action==='follow'){$u=require_api_mutation_auth($pdo);$public=(string)($input['user_id']??'');$q=$pdo->prepare('SELECT id FROM users WHERE public_id=? AND status="active"');$q->execute([$public]);$target=(int)($q->fetchColumn()?:0);if(!$target||$target===(int)$u['id'])json_response(['ok'=>false,'error'=>['code'=>'INVALID_USER']],422);if(is_blocked($pdo,(int)$u['id'],$target))json_response(['ok'=>false,'error'=>['code'=>'BLOCKED']],403);$q=$pdo->prepare('SELECT 1 FROM follows WHERE follower_user_id=? AND followed_user_id=?');$q->execute([$u['id'],$target]);if($q->fetchColumn()){$pdo->prepare('DELETE FROM follows WHERE follower_user_id=? AND followed_user_id=?')->execute([$u['id'],$target]);$following=false;}else{$pdo->prepare('INSERT INTO follows(follower_user_id,followed_user_id) VALUES(?,?)')->execute([$u['id'],$target]);$following=true;}json_response(['ok'=>true,'data'=>['following'=>$following]]);}
if($action==='save'){$u=require_api_mutation_auth($pdo);$q=$pdo->prepare("SELECT id FROM annotations WHERE public_id=? AND visibility='public' AND status='published'");$q->execute([(string)($input['annotation_id']??'')]);$id=(int)($q->fetchColumn()?:0);if(!$id)json_response(['ok'=>false,'error'=>['code'=>'NOT_FOUND']],404);$q=$pdo->prepare('SELECT 1 FROM saved_annotations WHERE user_id=? AND annotation_id=?');$q->execute([$u['id'],$id]);if($q->fetchColumn()){$pdo->prepare('DELETE FROM saved_annotations WHERE user_id=? AND annotation_id=?')->execute([$u['id'],$id]);$saved=false;}else{$pdo->prepare('INSERT INTO saved_annotations(user_id,annotation_id) VALUES(?,?)')->execute([$u['id'],$id]);$saved=true;}json_response(['ok'=>true,'data'=>['saved'=>$saved]]);}
if($action==='comment'){$u=require_api_mutation_auth($pdo);$body=trim((string)($input['body']??''));if($body===''||mb_strlen($body)>5000)json_response(['ok'=>false,'error'=>['code'=>'INVALID_COMMENT']],422);$q=$pdo->prepare("SELECT id,user_id FROM annotations WHERE public_id=? AND visibility='public' AND status='published'");$q->execute([(string)($input['annotation_id']??'')]);$a=$q->fetch();if(!$a)json_response(['ok'=>false,'error'=>['code'=>'NOT_FOUND']],404);if(is_blocked($pdo,(int)$u['id'],(int)$a['user_id']))json_response(['ok'=>false,'error'=>['code'=>'BLOCKED']],403);$pdo->prepare('INSERT INTO comments(annotation_id,user_id,body) VALUES(?,?,?)')->execute([$a['id'],$u['id'],$body]);json_response(['ok'=>true,'data'=>['created'=>true]],201);}
if($action==='presence'){$u=require_api_mutation_auth($pdo);$sourceId=ext_source_id($pdo,(string)($input['source']??''));if(!$sourceId)json_response(['ok'=>false,'error'=>['code'=>'SOURCE_NOT_FOUND']],404);$mode=(string)($input['mode']??$u['live_presence_mode']);if(!in_array($mode,['visible','team_only','cloaked','off'],true))$mode='cloaked';$pdo->prepare('UPDATE users SET live_presence_mode=? WHERE id=?')->execute([$mode,$u['id']]);if($mode==='off')$pdo->prepare('DELETE FROM page_presence_sessions WHERE source_id=? AND user_id=?')->execute([$sourceId,$u['id']]);else $pdo->prepare('INSERT INTO page_presence_sessions(source_id,user_id,presence_mode,last_seen_at) VALUES(?,?,?,NOW()) ON DUPLICATE KEY UPDATE presence_mode=VALUES(presence_mode),last_seen_at=NOW()')->execute([$sourceId,$u['id'],$mode]);$q=$pdo->prepare("SELECT p.user_id,p.presence_mode,u.public_id,u.username,u.display_name,EXISTS(SELECT 1 FROM follows f WHERE f.follower_user_id=? AND f.followed_user_id=p.user_id) is_following FROM page_presence_sessions p JOIN users u ON u.id=p.user_id WHERE p.source_id=? AND p.last_seen_at>=DATE_SUB(NOW(),INTERVAL 90 SECOND) AND p.presence_mode<>'off'");$q->execute([$u['id'],$sourceId]);$visible=[];$total=0;$following=0;foreach($q->fetchAll() as $r){if(is_blocked($pdo,(int)$u['id'],(int)$r['user_id']))continue;$total++;if($r['presence_mode']==='visible'){$visible[]=['public_id'=>$r['public_id'],'username'=>$r['username'],'display_name'=>$r['display_name'],'following'=>(bool)$r['is_following']];if($r['is_following'])$following++;}}json_response(['ok'=>true,'data'=>['total'=>$total,'visible'=>$visible,'following_visible'=>$following,'mode'=>$mode]]);}
if($action==='live'){$u=require_api_user($pdo);$sourceId=ext_source_id($pdo,(string)($input['source']??''));if(!$sourceId)json_response(['ok'=>false,'error'=>['code'=>'SOURCE_NOT_FOUND']],404);$q=$pdo->prepare("SELECT lm.id,lm.body,lm.source_timestamp_seconds,lm.created_at,u.public_id user_public_id,u.username,u.display_name FROM live_messages lm JOIN users u ON u.id=lm.user_id WHERE lm.source_id=? AND lm.room_type='public' AND NOT EXISTS(SELECT 1 FROM blocks b WHERE (b.blocker_user_id=? AND b.blocked_user_id=lm.user_id) OR (b.blocker_user_id=lm.user_id AND b.blocked_user_id=?)) ORDER BY lm.id DESC LIMIT 100");$q->execute([$sourceId,$u['id'],$u['id']]);json_response(['ok'=>true,'data'=>['messages'=>array_reverse($q->fetchAll())]]);}
if($action==='live_message'){$u=require_api_mutation_auth($pdo);$body=trim((string)($input['body']??''));if($body===''||mb_strlen($body)>3000)json_response(['ok'=>false,'error'=>['code'=>'INVALID_MESSAGE']],422);if($u['live_presence_mode']!=='visible'&&empty($input['reveal_identity']))json_response(['ok'=>false,'error'=>['code'=>'IDENTITY_DISCLOSURE_REQUIRED','message'=>'Posting publicly reveals your identity for this message.']],409);$sourceId=ext_source_id($pdo,(string)($input['source']??''));if(!$sourceId)json_response(['ok'=>false,'error'=>['code'=>'SOURCE_NOT_FOUND']],404);$timestamp=isset($input['timestamp'])?(float)$input['timestamp']:null;$pdo->prepare("INSERT INTO live_messages(source_id,user_id,room_type,body,source_timestamp_seconds) VALUES(?,?,'public',?,?)")->execute([$sourceId,$u['id'],$body,$timestamp]);json_response(['ok'=>true,'data'=>['created'=>true]],201);}
