if($action==='publish'){$u=require_api_mutation_auth($pdo);$url=trim((string)($input['url']??''));$selected=trim((string)($input['selected_text']??''));$comment=trim((string)($input['commentary']??''));$type=(string)($input['capture_type']??'text');$start=isset($input['start_seconds'])?(float)$input['start_seconds']:null;$end=isset($input['end_seconds'])?(float)$input['end_seconds']:null;if(!filter_var($url,FILTER_VALIDATE_URL))json_response(['ok'=>false,'error'=>['code'=>'INVALID_URL']],422);if(!in_array($type,['text','video_clip','audio_clip','image_region','page_region'],true))json_response(['ok'=>false,'error'=>['code'=>'INVALID_CAPTURE_TYPE']],422);if(in_array($type,['video_clip','audio_clip'],true)&&($start===null||$end===null||$end<=$start||($end-$start)>90))json_response(['ok'=>false,'error'=>['code'=>'CLIP_TOO_LONG','message'=>'Clips must be 90 seconds or less.']],422);if($selected===''&&$comment===''&&!in_array($type,['video_clip','audio_clip','image_region','page_region'],true))json_response(['ok'=>false,'error'=>['code'=>'EMPTY_ANNOTATION']],422);try{$contextPath=save_data_url_image((string)($input['screenshot_context']??''),'context');$targetPath=save_data_url_image((string)($input['screenshot_target']??''),'target');}catch(Throwable $e){json_response(['ok'=>false,'error'=>['code'=>'SNAPSHOT_INVALID','message'=>$e->getMessage()]],422);}$canonical=canonicalize_url($url);$pageText=(string)($input['page_text']??'');$pageHash=hash('sha256',$pageText);$targetHash=hash('sha256',$selected);$pdo->beginTransaction();try{$source=ensure_source($pdo,$canonical,$input['title']??null,$input['media_type']??null);$sourceId=(int)$source['id'];$versionId=(int)($source['current_version_id']??0);$currentHash=null;if($versionId){$q=$pdo->prepare('SELECT content_hash FROM source_versions WHERE id=?');$q->execute([$versionId]);$currentHash=$q->fetchColumn()?:null;}if(!$versionId||($pageText!==''&&$currentHash!==$pageHash)){$q=$pdo->prepare('SELECT COALESCE(MAX(version_number),0)+1 FROM source_versions WHERE source_id=?');$q->execute([$sourceId]);$next=(int)$q->fetchColumn();$q=$pdo->prepare('INSERT INTO source_versions(source_id,version_number,final_url,title,extracted_text,content_hash,target_content_hash,screenshot_path,metadata_json) VALUES(?,?,?,?,?,?,?,?,?)');$q->execute([$sourceId,$next,$canonical,$input['title']??null,$pageText?:null,$pageHash,$targetHash,$contextPath,json_encode(['media_type'=>$input['media_type']??null])]);$versionId=(int)$pdo->lastInsertId();$pdo->prepare('UPDATE sources SET current_version_id=?,title=COALESCE(?,title),status=? WHERE id=?')->execute([$versionId,$input['title']??null,$next>1?'updated':'current',$sourceId]);}$q=$pdo->prepare('INSERT INTO captures(public_id,source_id,source_version_id,user_id,capture_type,selected_text,start_seconds,end_seconds,screenshot_target_path,screenshot_context_path,selector_json) VALUES(?,?,?,?,?,?,?,?,?,?,?)');$q->execute([ulid_like(),$sourceId,$versionId,$u['id'],$type,$selected?:null,$start,$end,$targetPath,$contextPath,json_encode($input['selector']??null)]);$captureId=(int)$pdo->lastInsertId();$visibility=in_array($input['visibility']??'public',['public','private'],true)?$input['visibility']:'public';$publicId=ulid_like();$pdo->prepare('INSERT INTO annotations(public_id,user_id,source_id,source_version_id,capture_id,text_commentary,visibility,status) VALUES(?,?,?,?,?,?,?,"published")')->execute([$publicId,$u['id'],$sourceId,$versionId,$captureId,$comment?:null,$visibility]);if(in_array($type,['video_clip','audio_clip'],true)){$duration=$end-$start;$pdo->prepare('INSERT INTO media_derivatives(capture_id,media_type,duration_seconds,resolution_label,processing_status) VALUES(?,?,?,?,"queued")')->execute([$captureId,$type==='video_clip'?'video':'audio',$duration,$type==='video_clip'?'240p':null]);$derivative=(int)$pdo->lastInsertId();$pdo->prepare('INSERT INTO media_jobs(derivative_id,source_url,start_seconds,end_seconds) VALUES(?,?,?,?)')->execute([$derivative,$canonical,$start,$end]);}$pdo->commit();json_response(['ok'=>true,'data'=>['annotation_id'=>$publicId,'url'=>'/annotation.php?id='.$publicId,'media_queued'=>in_array($type,['video_clip','audio_clip'],true)]],201);}catch(Throwable $e){if($pdo->inTransaction())$pdo->rollBack();json_response(['ok'=>false,'error'=>['code'=>'PUBLISH_FAILED','message'=>'Unable to publish annotation.']],500);}}
json_response(['ok'=>false,'error'=>['code'=>'UNKNOWN_ACTION']],404);
